window.kbPageData["views/entry/k-b5ddb378c57bf659"] = {"key":"entry/k-b5ddb378c57bf659","state":{"route":"entry/k-b5ddb378c57bf659"},"node":{"id":"k-b5ddb378c57bf659","mode":"k","title":"公共服务标准化","type":"原理与机制","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":["公共服务标准化以规范服务内容为核心"],"qs":["江苏 2023 A类 行测#14"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"公共服务标准化是通过制定和实施统一标准，明确公共服务的内容、流程和质量要求，使服务提供有共同依据。","review":{"definition":"公共服务标准化是通过制定和实施统一标准，明确公共服务的内容、流程和质量要求，使服务提供有共同依据。","explanation":"江苏 2023 A类行测第14题中，统一后的“马”字保留了秦国字形的主要特征。秦以已有文字为基础规范通行写法，解决各地书写不一致给治理带来的困难。对应到公共服务，就是把服务提供什么、应达到什么要求明确为共同标准，因此选D。D项的“以规范服务内容为核心”概括的是本题类比。“马”字图示无法证明增加服务环节是必经阶段，也无法据字形的易辨性或美观程度确定标准化的根本导向或最终目标。","references":[],"evidence":"说明公共服务标准化以规范服务内容为核心","disposition":"题内说明","basis":"据原题和解析编释。"}},"questions":{"江苏 2023 A类 行测#14":{"paper":"江苏 2023 A类 行测","n":14,"mod":"常识判断","src":["22304fe4c340e19d7902.pdf",2],"asrc":["be17f9afe070cf13a0fb.pdf",6],"card":"ff3217b273af2ff1869f9b13","links":[{"id":"k-b5ddb378c57bf659","role":"直接考查","why":"通过以秦国文字为基础规范通行文字，引出对服务内容制定统一标准的原则。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-b5ddb378c57bf659":[["江苏 2023 A类 行测#14"]]}};
